function heapSort(a) {
  const n = a.length;
  const siftDown = (start, end) => {
    let root = start;
    while (2 * root + 1 <= end) {
      let child = 2 * root + 1;
      if (child + 1 <= end && a[child] < a[child + 1]) child++;
      if (a[root] < a[child]) {
        [a[root], a[child]] = [a[child], a[root]];
        root = child;
      } else return;
    }
  };
  for (let start = Math.floor((n - 2) / 2); start >= 0; start--) siftDown(start, n - 1);
  for (let end = n - 1; end > 0; end--) {
    [a[0], a[end]] = [a[end], a[0]];
    siftDown(0, end - 1);
  }
  return a;
}

